/**
 * @agent-cms/runtime — public API contract for AgentCMS external plugins and themes.
 *
 * Describes CMS runtime API **1.5.0** (`CMS_API_VERSION`; bundles declaring an
 * `apiVersion` between `CMS_API_MIN_VERSION` = 1.0.0 and 1.5.0 are loaded).
 *
 * What this file is
 * -----------------
 * External bundles (plugins and themes built outside the AgentCMS repo) import
 * the admin's live API from the bare specifier `@agent-cms/runtime`. At build
 * time that specifier is EXTERNALISED (never bundled); at runtime the admin's
 * import-map redirects it to `<admin>/runtime/cms-runtime.js`, which re-exports
 * the values the admin put on `window.__AGENTCMS_RUNTIME__`. This file gives
 * that specifier its types. It is self-contained: the only external types it
 * uses come from `react` (install `@types/react`). Firebase, Tiptap and
 * i18next types are replaced by documented structural stand-ins.
 *
 * Wiring (tsconfig.json of your plugin / theme project)
 * -----------------------------------------------------
 *   {
 *     "compilerOptions": {
 *       "strict": true,
 *       "jsx": "react-jsx",
 *       "lib": ["ES2020", "DOM", "DOM.Iterable"],
 *       "moduleResolution": "bundler",
 *       "paths": {
 *         "@agent-cms/runtime": ["./node_modules/@agent-cms/agentcms/types/agentcms-runtime.d.ts"]
 *       }
 *     }
 *   }
 *
 * and in vite.config.ts keep `@agent-cms/runtime`, `react`, `react/jsx-runtime`,
 * `react-dom`, `react-dom/client` and `react-i18next` in `rollupOptions.external`
 * (plus `inlineDynamicImports: true`: the admin only loads `bundle.js`).
 *
 * Ground rules
 * ------------
 * - Everything here runs IN THE BROWSER, inside the admin SPA. There is no server.
 * - Theme templates are rendered with `renderToStaticMarkup` at publish time:
 *   they must be pure functions of their (serializable) props — no hooks that
 *   fetch, no admin contexts, no effects.
 * - Site paths are relative to the site root WITHOUT a leading slash
 *   ("news/post.html", "data/menu.json"). Links inside HTML use a leading slash
 *   ("/news/post.html"); sub-folder deployments are rewritten automatically.
 * - Never `fetch` the publish target yourself: use the site-file helpers
 *   (`uploadFile`, `deleteFile`, …) so batching, toasts and errors stay consistent.
 *
 * This file is generated by hand from the admin sources and kept in sync by
 * `src/core/runtimeTypes.test.ts` in the AgentCMS repo.
 */

import type { ComponentType, ReactElement, ReactNode } from "react";

// ═══════════════════════════════════════════════════════════════════════════
// Stand-in types (replace Firebase / Tiptap / i18next / clsx types)
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Date value stored on posts, terms and users. Structurally identical to
 * Firebase's `Timestamp` class (instance side). Every backend hands out
 * objects with this shape. Use `toMillis()` / `toDate()`; fields may be
 * missing on freshly created drafts, so always use optional chaining
 * (`post.createdAt?.toMillis?.() ?? 0`).
 */
export interface Timestamp {
  readonly seconds: number;
  readonly nanoseconds: number;
  toDate(): Date;
  toMillis(): number;
  isEqual(other: Timestamp): boolean;
  toString(): string;
  toJSON(): { seconds: number; nanoseconds: number; type: string };
  valueOf(): string;
}

/**
 * A Tiptap `Editor` instance (`@tiptap/core`). Typed `any` so this file stays
 * dependency-free; if you install `@tiptap/core` yourself, cast:
 * `const ed = editor as import("@tiptap/core").Editor`.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type TiptapEditor = any;

/**
 * Tiptap `ChainedCommands` (`editor.chain().focus()…`). Typed `any`; cast to
 * `import("@tiptap/core").ChainedCommands` for full typing. Remember to call
 * `.run()` at the end of the chain.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type TiptapChainedCommands = any;

/**
 * Tiptap `Extensions` (array of `Node` / `Mark` / `Extension`). Typed loosely;
 * cast to `import("@tiptap/core").Extensions` if you need it.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type TiptapExtensions = any[];

/**
 * Minimal view of the admin's i18next instance. The real object is a full
 * `i18next` instance (cast to `import("i18next").i18n` if you depend on it).
 * In React components prefer `useTranslation("<namespace>")` from
 * `react-i18next` (also externalised and shared with the admin).
 */
export interface I18nInstance {
  /** Current admin UI language ("en", "fr", …). */
  readonly language: string;
  readonly languages: readonly string[];
  /** Translate a key. Use `{ ns: "<plugin-id>" }` to target your namespace. */
  t(key: string | string[], options?: Record<string, unknown>): string;
  exists(key: string | string[], options?: Record<string, unknown>): boolean;
  /**
   * Translator bound to a language + namespace. Theme templates use it to
   * render in the SITE language (not the admin user's):
   * `i18n.getFixedT(pickPublicLocale(site.settings.language), "theme-<id>")`.
   */
  getFixedT(lng: string, ns?: string): (key: string, options?: Record<string, unknown>) => string;
  /** Raw resource lookup (`undefined` when missing). Handy in publish-time filters where there is no `t()`. */
  getResource(lng: string, ns: string, key: string): any;
  changeLanguage(lng?: string): Promise<unknown>;
  /** Add translations at runtime (plugin/theme bundles are loaded automatically from `manifest.i18n`). */
  addResourceBundle(
    lng: string,
    ns: string,
    resources: object,
    deep?: boolean,
    overwrite?: boolean,
  ): unknown;
  hasResourceBundle(lng: string, ns: string): boolean;
}

/** Anything `cn()` (clsx) accepts. */
export type ClassValue =
  | ClassArray
  | ClassDictionary
  | string
  | number
  | bigint
  | null
  | boolean
  | undefined;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type ClassDictionary = Record<string, any>;
export type ClassArray = ClassValue[];

/** Signed-in admin user (subset of Firebase Auth's `User`; synthesised on the other backends). */
export interface AuthUser {
  readonly uid: string;
  readonly email: string | null;
  readonly displayName: string | null;
  readonly emailVerified: boolean;
  readonly photoURL: string | null;
}

// ═══════════════════════════════════════════════════════════════════════════
// Domain data model (core/types.ts)
// ═══════════════════════════════════════════════════════════════════════════

/** Admin UI locales shipped with translations. */
export type AdminLocale = "en" | "fr" | "de" | "es" | "nl" | "pt" | "ko";
export type UserRole = "admin" | "editor";

export interface UserPreferences {
  adminLocale: AdminLocale;
}

/** Public-side social network identifiers (curated list). */
export type SocialNetwork =
  | "twitter"
  | "linkedin"
  | "instagram"
  | "mastodon"
  | "bluesky"
  | "github"
  | "website";

/** One social profile entry on a user record. `visible: false` keeps the URL but hides it publicly. */
export interface SocialEntry {
  url: string;
  visible: boolean;
}

/** A user (admin or editor). Email is admin-only data — never render it publicly. */
export interface UserRecord {
  id: string;
  email: string;
  /** Legacy free-form name; prefer firstName / lastName. */
  displayName?: string;
  firstName?: string;
  lastName?: string;
  /** Public job title shown under the author name. */
  title?: string;
  bio?: string;
  /** Media id of the avatar (resolve with the media helpers). */
  avatarMediaId?: string;
  socials?: Partial<Record<SocialNetwork, SocialEntry>>;
  role: UserRole;
  disabled: boolean;
  preferences?: UserPreferences;
  createdAt?: Timestamp;
  createdBy?: string;
}

/** Posts and pages share one collection, distinguished by `type`. */
export type PostType = "post" | "page";
export type PostStatus = "draft" | "online";

/** SEO overrides (`<title>`, `<meta description>`, `og:image`). */
export interface SeoMeta {
  title?: string;
  description?: string;
  ogImage?: string;
}

/**
 * A post or a page. URL: page → `<slug>.html`; post with a category →
 * `<category-slug>/<slug>.html`; post without → `<slug>.html` (see `buildPostUrl`).
 */
export interface Post {
  id: string;
  type: PostType;
  title: string;
  slug: string;
  /** Body as Markdown (may contain block marker `<div data-cms-…>` HTML). */
  contentMarkdown: string;
  excerpt?: string;
  /** Media id of the featured image. */
  heroMediaId?: string;
  authorId: string;
  /** Tags + at most one category. */
  termIds: string[];
  /** The category (drives the URL). */
  primaryTermId?: string;
  status: PostStatus;
  seo?: SeoMeta;
  createdAt?: Timestamp;
  updatedAt?: Timestamp;
  publishedAt?: Timestamp;
  /** Site path the post is currently live at (publisher bookkeeping — don't write it). */
  lastPublishedPath?: string;
  /** Old paths whose deletion failed; retried on next publish (publisher bookkeeping). */
  previousPublishedPaths?: string[];
  /** Hash of the last uploaded HTML (publisher bookkeeping). */
  lastPublishedHash?: string;
  /** Original URL on an imported source system (opaque metadata). */
  legacyUrl?: string;
  /** Opaque per-locale plugin data keyed by language tag (API ≥ 1.2). The core never reads it. */
  translations?: Record<string, unknown>;
  /** Per-locale published paths, written by variant-publishing plugins (API ≥ 1.2). */
  lastPublishedPathsByLocale?: Record<string, string>;
}

export type TermType = "category" | "tag";

/** A category or a tag. Only categories have a public archive (`<slug>/index.html`). */
export interface Term {
  id: string;
  type: TermType;
  name: string;
  slug: string;
  description?: string;
  parentId?: string;
  /** Archive SEO overrides; fall back to name / description. */
  seo?: SeoMeta;
  createdAt?: Timestamp;
  updatedAt?: Timestamp;
  lastPublishedPath?: string;
  /** Opaque per-locale plugin data (API ≥ 1.2). */
  translations?: Record<string, unknown>;
}

/** One pre-rendered variant of an uploaded image. */
export interface MediaVariant {
  url: string;
  width: number;
  height: number;
  bytes: number;
}

/**
 * A media library entry. Modern uploads carry `formats` (one variant per
 * theme format + admin formats); legacy uploads only `url`. Don't read the
 * shape directly: use `mediaToView` / `pickMediaUrl`.
 */
export interface Media {
  id: string;
  /** Original filename, for display. */
  name: string;
  contentType: string;
  /** Sum of every variant's size in bytes. */
  size: number;
  /** Folder holding every variant, e.g. "media/2026/05/photo-a3f7b2". */
  storageBase?: string;
  formats?: Record<string, MediaVariant>;
  defaultFormat?: string;
  /** Legacy single-file uploads. */
  storagePath?: string;
  /** Legacy single-file uploads. */
  url?: string;
  alt?: string;
  caption?: string;
  /** Epoch milliseconds. */
  uploadedAt: number;
  uploadedBy: string;
}

export type ImageFit = "cover" | "contain";

/** Processing rule for one image variant. */
export interface ImageFormat {
  width: number;
  height: number;
  /** "cover" crops to fill; "contain" fits inside, preserving ratio. */
  fit?: ImageFit;
  /** 0..100, overrides `ImageFormatConfig.quality` for this variant. */
  quality?: number;
}

/** Image catalog declared by a theme (`ThemeManifest.imageFormats`). */
export interface ImageFormatConfig {
  /** Accepted upload FILE EXTENSIONS, with the dot: [".jpg", ".jpeg", ".png", ".webp", ".gif"]. MIME types make every upload fail. */
  inputFormats: string[];
  outputFormat: "webp" | "jpeg" | "png";
  /** 0..100. */
  quality: number;
  formats: Record<string, ImageFormat>;
  defaultFormat: string;
}

/** A menu entry as stored in settings (internal ref OR external URL). */
export interface MenuItem {
  id: string;
  label: string;
  ref?: { kind: "post" | "term" | "home"; id?: string };
  externalUrl?: string;
  children?: MenuItem[];
  /** Per-language label overrides. */
  translations?: Record<string, { label?: string }>;
}

/** Editor-only typography (the admin WYSIWYG canvas, not the public site). */
export interface EditorStyle {
  fontFamily?: string;
  bodySize?: string;
  h1Size?: string;
  h2Size?: string;
  h3Size?: string;
}

/** Site-wide settings (`settings/site`). One live subscription keeps it fresh in the admin. */
export interface SiteSettings {
  title: string;
  description: string;
  /** BCP-47 tag of the PUBLIC site (`<html lang>`), independent of the admin UI language. */
  language: string;
  /** Public base URL, e.g. "https://example.com" (may be empty on fresh installs). */
  baseUrl: string;
  activeThemeId: string;
  enabledPlugins: Record<string, boolean>;
  homeMode: "latest-posts" | "static-page";
  homePageId?: string;
  postsPerPage: number;
  menus: {
    header: MenuItem[];
    footer: MenuItem[];
  };
  /** Per-plugin config blobs keyed by plugin id (JSON-serializable). Read yours with `settings.pluginConfigs?.["<id>"]`. */
  pluginConfigs?: Record<string, unknown>;
  /** Per-theme config blobs keyed by theme id. */
  themeConfigs?: Record<string, unknown>;
  editorStyle?: EditorStyle;
  paginationMode?: "global" | "paginated";
  /** When true every page gets `noindex,nofollow`. */
  discourageIndexing?: boolean;
}

// ═══════════════════════════════════════════════════════════════════════════
// Theme contract (themes/types.ts)
// ═══════════════════════════════════════════════════════════════════════════

/** A menu entry with its href resolved (no raw post/term refs). */
export interface ResolvedMenuItem {
  id: string;
  label: string;
  href: string;
  children?: ResolvedMenuItem[];
  /** Per-language labels; the runtime menu loader picks `labels[<html lang>]`. */
  labels?: Record<string, string>;
}

/** A visible social link of an author. */
export interface AuthorSocial {
  network: SocialNetwork;
  url: string;
}

/** Public author data resolved by the publisher (no email). */
export interface AuthorView {
  id: string;
  displayName: string;
  /** Root-absolute URL of the author's archive page, e.g. "/author/ada-writer.html". */
  url?: string;
  title?: string;
  bio?: string;
  avatar?: MediaView;
  socials?: AuthorSocial[];
}

/** Resolved media for templates. Pick a size with `pickFormat(view, "large")`. */
export interface MediaView {
  alt?: string;
  caption?: string;
  /** Fallback format name. */
  default: string;
  formats: Record<string, { url: string; width: number; height: number }>;
}

/** Site-wide context every template receives as `site`. */
export interface SiteContext {
  settings: SiteSettings;
  /** Menus with hrefs filled in (menus are ALSO loaded at runtime from /data/menu.json). */
  resolvedMenus: {
    header: ResolvedMenuItem[];
    footer: ResolvedMenuItem[];
  };
  /** Site path of the active theme's CSS, e.g. "theme-assets/default.css". Link it as "/" + path. */
  themeCssPath: string;
  /** Active theme config (defaults merged with saved values). Cast to your config type. */
  themeConfig?: unknown;
  /** Href of the "home" link for this page (e.g. "/fr/index.html"); default "/index.html". */
  homePath?: string;
}

/**
 * Props of the theme's `base` layout (the HTML document shell).
 * The BaseLayout MUST emit `<meta name="x-cms-head-extra" />` inside `<head>`
 * and `<script type="application/x-cms-body-end" />` before `</body>`, or
 * plugin head/body injections silently no-op. Use `canonicalUrl(site.settings.baseUrl, currentPath)`
 * for `<link rel="canonical">`.
 */
export interface BaseLayoutProps {
  site: SiteContext;
  pageTitle: string;
  pageDescription?: string;
  ogImage?: string;
  /** Site path being rendered, e.g. "news/article.html" (no leading slash). */
  currentPath: string;
  /** `<html lang>` override for this page; fall back to `site.settings.language`. */
  currentLocale?: string;
  /** Never set by the core: plugins' head markup goes through the `<meta name="x-cms-head-extra" />` sentinel. */
  extraHead?: string;
  children: ReactNode;
}

/** A post enriched for listing cards (URL, hero, category, date label resolved). */
export type CardPost = Post & {
  url: string;
  hero?: MediaView;
  category?: { name: string; url: string };
  dateLabel?: string;
};

/** Props of the `single` template (posts and pages). */
export interface SingleTemplateProps {
  post: Post;
  /** Sanitized HTML body — render with `dangerouslySetInnerHTML`. */
  bodyHtml: string;
  author?: AuthorView;
  hero?: MediaView;
  primaryTerm?: Term;
  tags: Term[];
}

/** "See full archives →" link injected by the archives plugin. */
export interface ArchivesLink {
  href: string;
  label: string;
}

/** Props of the `home` template. */
export interface HomeTemplateProps {
  posts: CardPost[];
  /** Set when `settings.homeMode === "static-page"`. */
  staticPage?: { post: Post; bodyHtml: string };
  archivesLink?: ArchivesLink;
  /** Pre-rendered HTML from theme blocks (themes may ignore). */
  heroHtml?: string;
  listHtml?: string;
  mostReadHtml?: string;
  promoCardHtml?: string;
}

/** Props of the `category` archive template. */
export interface CategoryTemplateProps {
  term: Term;
  posts: CardPost[];
  /** Per-category RSS feed URL when the RSS plugin has one. */
  categoryRssUrl?: string;
  archivesLink?: ArchivesLink;
  allCategories?: Term[];
  popularTags?: Term[];
}

/** Props of the `author` archive template. */
export interface AuthorTemplateProps {
  author: AuthorView;
  posts: CardPost[];
}

/** Props of the `notFound` (404.html) template. */
export interface NotFoundTemplateProps {
  message?: string;
}

/** Theme settings page declaration (route /theme-settings). Stored in `settings.themeConfigs[<id>]`. */
/**
 * Documentation of a plugin's or theme's settings (API ≥ 1.5), read by agents
 * through `agentcms plugins|themes config <id> --schema`: one entry per
 * setting, keyed by its dot path in the config ("home.variant"). An entry on
 * an object path ("style.vars") documents the whole map.
 */
export interface SettingDoc {
  description: string;
  /** Closed list of accepted values (the CLI refuses any other). */
  values?: ReadonlyArray<string | number | boolean>;
  min?: number;
  max?: number;
  /** Expected format of a free value: "hex color", "CSS length", "page id", "URL"… */
  format?: string;
}
export type SettingsSchema = Record<string, SettingDoc>;

export interface ThemeSettingsPageDef<TConfig = unknown> {
  /** i18n key, resolved in the `theme-<id>` namespace. */
  navLabelKey: string;
  /** Merged with the stored value before rendering. */
  defaultConfig: TConfig;
  component: ComponentType<ThemeSettingsPageProps<TConfig>>;
  // Optional (API ≥ 1.5): what each setting does and accepts — shown by
  // `agentcms themes config <id> --schema` and checked on --set / --merge.
  schema?: SettingsSchema;
}

export interface ThemeSettingsPageProps<TConfig = unknown> {
  config: TConfig;
  /** Persists the whole config (replaces the theme's slot). */
  save: (next: TConfig) => Promise<void>;
}

/**
 * Default export of a theme `bundle.js`. `id` must match the theme's
 * manifest.json id. Templates are rendered to static HTML at publish time.
 */
export interface ThemeManifest<TConfig = unknown> {
  id: string;
  name: string;
  version: string;
  description?: string;
  /** Markdown documentation (e.g. `import readme from "../README.md?raw"`): "Learn more" on the Themes page. */
  readme?: string;
  /** Image variants generated on upload; templates ask for them by name with `pickFormat`. */
  imageFormats?: ImageFormatConfig;
  /** Informational path of the stylesheet source (relative to the theme folder). */
  scssEntry: string;
  /** Compiled CSS uploaded to `theme-assets/<id>.css` by "Sync theme assets". */
  cssText: string;
  /** Optional runtime script uploaded as `theme-assets/<id>-menu.js` (menu loader). */
  jsText?: string;
  /** Optional runtime script uploaded as `theme-assets/<id>-posts.js`. */
  jsTextPosts?: string;
  /** Seed Markdown for new posts / pages. */
  defaultPostMarkdown?: {
    post?: string;
    page?: string;
  };
  templates: {
    base: ComponentType<BaseLayoutProps>;
    home: ComponentType<HomeTemplateProps & { site: SiteContext }>;
    single: ComponentType<SingleTemplateProps & { site: SiteContext }>;
    category: ComponentType<CategoryTemplateProps & { site: SiteContext }>;
    author: ComponentType<AuthorTemplateProps & { site: SiteContext }>;
    notFound: ComponentType<NotFoundTemplateProps & { site: SiteContext }>;
  };
  settings?: ThemeSettingsPageDef<TConfig>;
  /** Translations, loaded into the `theme-<id>` i18next namespace. */
  i18n?: Partial<Record<AdminLocale, Record<string, unknown>>>;
  /** Bakes the user's config into the uploaded CSS (otherwise `cssText` is uploaded verbatim). */
  compileCss?: (config: TConfig) => string;
  /** Editor blocks registered while this theme is active (typed blocks, e.g. `BlockManifest<MyAttrs>`, are accepted as-is). */
  blocks?: BlockManifest<any>[];
  /** Called when the theme becomes active (after its blocks are registered). Hook filters here. */
  register?: (api: PluginApi, ctx?: { settings: SiteSettings }) => void;
}

// ═══════════════════════════════════════════════════════════════════════════
// Plugin contract (plugins/index.ts)
// ═══════════════════════════════════════════════════════════════════════════

/** Plugin settings page declaration (route /settings/plugin/<id>). Stored in `settings.pluginConfigs[<id>]`. */
export interface PluginSettingsPageDef<TConfig = unknown> {
  /** i18n key for the tab label, resolved in the plugin's namespace (its id). */
  navLabelKey: string;
  defaultConfig: TConfig;
  component: ComponentType<PluginSettingsPageProps<TConfig>>;
  // Optional (API ≥ 1.5): what each setting does and accepts — shown by
  // `agentcms plugins config <id> --schema` and checked on --set / --merge.
  schema?: SettingsSchema;
}

export interface PluginSettingsPageProps<TConfig = unknown> {
  /** `defaultConfig` shallowly merged with the stored value (merge nested objects yourself). */
  config: TConfig;
  /** Persists the whole config (`updatePluginConfig` under the hood). */
  save: (next: TConfig) => Promise<void>;
}

/**
 * Default export of a plugin `bundle.js`. `id` must match manifest.json's id.
 * `register(api)` is re-run on every registry reset (settings change, plugin
 * toggle) — keep it idempotent and side-effect free apart from `api.*` calls.
 */
export interface PluginManifest<TConfig = unknown> {
  id: string;
  name: string;
  version: string;
  description?: string;
  author?: string;
  /** Long-form Markdown shown in a "Learn more" modal. */
  readme?: string;
  register: (api: PluginApi) => void;
  settings?: PluginSettingsPageDef<TConfig>;
  /** Translations, loaded into the i18next namespace named after the plugin id. */
  i18n?: Partial<Record<AdminLocale, Record<string, unknown>>>;
}

// ═══════════════════════════════════════════════════════════════════════════
// Hooks + registries (core/pluginRegistry.ts and friends)
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Filter handler: receives the current value plus hook-specific extra args,
 * returns the (possibly modified) value. Extra args are typed `unknown[]` —
 * narrow them yourself: `(html, ...rest) => { const post = rest[0] as Post; … }`.
 */
export type FilterFn<T = unknown> = (value: T, ...args: unknown[]) => T | Promise<T>;
/** Action handler: side effect, return value ignored. Narrow args like filters. */
export type ActionFn = (...args: unknown[]) => void | Promise<void>;

/**
 * Filter hooks fired by the core and bundled plugins (documentation only —
 * `addFilter` accepts any string, so plugins can define their own hooks).
 *
 * - `post.markdown.before` async `(md: string, post: Post)` — edit Markdown before rendering.
 * - `post.html.body` async `(html: string, post: Post)` — edit rendered body HTML (themes resolve block markers here; `getCurrentPublishContext()` gives the full ctx).
 * - `post.template.props` async `(props: SingleTemplateProps, post: Post)`.
 * - `page.head.extra` **SYNC** `(html: string, baseProps: BaseLayoutProps)` — append `<head>` markup. Async handlers THROW.
 * - `page.body.end` **SYNC** `(html: string, baseProps: BaseLayoutProps)` — append markup before `</body>`.
 * - `menu.json.resolved` async `(menu: MenuJson, ctx: MenuFilterContext)`.
 * - `publish.additional` async `(extras: AdditionalRender[], post: Post, ctx: PublishContext)` — extra files per post; orphans tracked via `Post.lastPublishedPathsByLocale`.
 * - `publish.extraListings` async `(extras: AdditionalListingRender[], ctx: PublishContext)` — extra listing files.
 * - `sitemap.urlset.namespaces` sync, `sitemap.url.entry` sync, `sitemap.urls.extra` sync,
 *   `sitemap.index.extra` sync, `sitemap.news.locales` async — sitemap plugin.
 * - `rss.site.locales` async — RSS plugin.
 */
export type KnownFilterHook =
  | "post.markdown.before"
  | "post.html.body"
  | "post.template.props"
  | "page.head.extra"
  | "page.body.end"
  | "menu.json.resolved"
  | "publish.additional"
  | "publish.extraListings"
  | "sitemap.urlset.namespaces"
  | "sitemap.url.entry"
  | "sitemap.urls.extra"
  | "sitemap.index.extra"
  | "sitemap.news.locales"
  | "rss.site.locales";

/**
 * Action hooks fired by the core (documentation only).
 *
 * - `publish.before` `(post: Post, ctx: PublishContext)` — before rendering (also in bulk mode).
 * - `publish.after`, `publish.complete` `(post, ctx)` — after upload + listings refresh.
 * - `post.unpublished` `(post, ctx)` — after the post's files were deleted.
 * - `post.deleted` `(post, ctx)` — after the post was deleted.
 * - `regenerate.listings.before` `(ctx: PublishContext)`.
 *
 * `ctx` is already patched to reflect the transition (ctx.posts = the site AFTER the action).
 * `publish.after` / `publish.complete` / `post.unpublished` / `post.deleted` fire for
 * single-post actions only — bulk publishes, imports and "Regenerate all" skip them;
 * pair them with `api.registerRegenerationTarget` for derived files.
 */
export type KnownActionHook =
  | "publish.before"
  | "publish.after"
  | "publish.complete"
  | "post.unpublished"
  | "post.deleted"
  | "regenerate.listings.before";

/** Inserter grouping of a block. */
export type BlockCategory = "text" | "media" | "layout" | "embed" | "advanced";

/** Resources the host page hands to `BlockManifest.insert`. */
export interface BlockInsertContext {
  /**
   * Opens the media picker; resolves null when cancelled. `id` is the media
   * id: store it to resolve every variant at publish time
   * (`getCurrentPublishContext()?.media.get(id)` → `mediaToView` → `pickFormat`).
   */
  pickMedia?: () => Promise<{ id?: string; url: string; alt?: string } | null>;
}

/** Props of a block inspector (Block tab of the editor sidebar). */
export interface BlockInspectorProps<TAttrs = Record<string, unknown>> {
  attrs: TAttrs;
  /** Writes attrs back into the Tiptap node. */
  updateAttrs: (next: Partial<TAttrs>) => void;
  editor: TiptapEditor;
}

/**
 * Editor block. Blocks usually serialize to Markdown as an HTML marker
 * (`<div data-cms-block="<id>" …></div>`) that a `post.html.body` filter
 * turns into real HTML at publish time.
 */
export interface BlockManifest<TAttrs = Record<string, unknown>> {
  /** Namespaced id: "<plugin-id>/<block>". */
  id: string;
  /** Tiptap node name. REQUIRED when the id contains a slash (slashes are invalid node names). */
  nodeName?: string;
  /** i18n key of the display name. */
  titleKey: string;
  /** i18n namespace (your plugin id); global namespace when omitted. */
  namespace?: string;
  /** Icon component taking `{ className? }`: an inline SVG component is simplest (lucide-react isn't provided by the admin — bundling it is possible but heavy). */
  icon: ComponentType<{ className?: string }>;
  category: BlockCategory;
  /** Inserts the block; call `.run()` on the chain. May be async. */
  insert: (chain: TiptapChainedCommands, ctx: BlockInsertContext) => Promise<void> | void;
  /** Tiptap Node/Mark/Extension list; picked up when the editor mounts. */
  extensions?: TiptapExtensions;
  isActive?: (editor: TiptapEditor) => boolean;
  inspector?: ComponentType<BlockInspectorProps<TAttrs>>;
}

/** Self-contained dashboard card (no props: fetch your own data). */
export interface DashboardCardManifest {
  /** "<plugin-id>/<card>". */
  id: string;
  /** Lower first; default 100. */
  priority?: number;
  component: ComponentType;
}

/** Props of a plugin Inspector tab in the post/page editor. */
export interface InspectorTabProps {
  /** Live draft of the post/page. */
  entity: Post;
  /** Patch the in-memory draft (marks the page dirty; committed by the host's Save). */
  updateEntity: (patch: Partial<Post>) => void;
  /** Persist the current draft right now. */
  save: () => Promise<void>;
}

/** Extra tab in the editor's right-hand Inspector (API ≥ 1.2). */
export interface InspectorTabManifest {
  /** "<plugin-id>/<tab>". */
  id: string;
  labelKey: string;
  namespace?: string;
  /** Default "all". */
  forKind?: "post" | "page" | "all";
  /** Small badge next to the label; undefined hides it. */
  badge?: (entity: Post) => string | number | undefined;
  /** Default 100. */
  priority?: number;
  component: ComponentType<InspectorTabProps>;
}

/** Props of a Categories/Tags editor section. */
export interface TermEditorSectionProps {
  term: Term;
  /** Patch the draft; committed when the row is saved. */
  updateTerm: (patch: Partial<Term>) => void;
}

/** Collapsible section in each Categories/Tags row (API ≥ 1.2). */
export interface TermEditorSectionManifest {
  id: string;
  /** Default "all". */
  termType?: "category" | "tag" | "all";
  priority?: number;
  component: ComponentType<TermEditorSectionProps>;
}

/** One tab of the editor variant strip. `primary` = the entity's own fields. */
export interface EditorVariant {
  id: string;
  label: string;
  badge?: string;
  primary: boolean;
}

/** Per-variant editable fields (everything else is shared by all variants). */
export interface VariantFields {
  title: string;
  slug: string;
  contentMarkdown: string;
  excerpt?: string;
  seo?: SeoMeta;
}

/** Live admin data passed to variant provider callbacks. */
export interface VariantContext {
  settings: SiteSettings;
  terms: Term[];
}

/**
 * Editor variant provider (API ≥ 1.3): a tab strip above the editor that
 * swaps title/slug/body/excerpt/SEO per variant (multilang, A/B, drafts).
 * At most one provider should return more than one variant per entity.
 */
export interface EditorVariantProvider {
  id: string;
  /** Called on every render — keep it cheap. */
  listVariants: (entity: Post, ctx: VariantContext) => EditorVariant[];
  /** Stored fields of a non-primary variant, or null when empty. */
  loadFields: (entity: Post, variantId: string, ctx: VariantContext) => VariantFields | null;
  /** Persist a non-primary variant; throw on failure. */
  saveFields: (
    entity: Post,
    variantId: string,
    fields: VariantFields,
    ctx: VariantContext,
  ) => Promise<void>;
  /** URL prefix shown before the slug, e.g. "fr/actualites/". */
  getSlugPathPrefix?: (
    entity: Post,
    variantId: string,
    fields: VariantFields,
    ctx: VariantContext,
  ) => string;
  /** URL suffix, default ".html". */
  getSlugPathSuffix?: (
    entity: Post,
    variantId: string,
    fields: VariantFields,
    ctx: VariantContext,
  ) => string;
  /** Error message (already translated) or null when valid. */
  validate?: (
    entity: Post,
    variantId: string,
    fields: VariantFields,
    ctx: VariantContext,
  ) => string | null;
  priority?: number;
}

/** "Force regenerate" entry in the Themes page Regenerate ▾ menu. */
export interface RegenerationTarget {
  /** Usually the plugin id. */
  id: string;
  /** Default: the target id. Themes pass "theme-<id>". */
  i18nNamespace?: string;
  labelKey: string;
  descriptionKey?: string;
  /** Default 100. */
  priority?: number;
  /** Runs with a fresh PublishContext; throws are caught and logged. Persist your own bookkeeping. */
  run: (ctx: PublishContext, log: PublishLogger) => Promise<void>;
}

/**
 * Object passed to `PluginManifest.register(api)` / `ThemeManifest.register(api)`.
 * Registrations are wiped and replayed on every registry reset, so call these
 * only from `register()`.
 */
export interface PluginApi {
  /** Register a filter. Lower priority runs first (default **10**), ties by registration order. */
  addFilter<T = unknown>(hook: string, fn: FilterFn<T>, priority?: number): void;
  /** Register an action. Lower priority runs first (default **10**). */
  addAction(hook: string, fn: ActionFn, priority?: number): void;
  /** Register an editor block (ignored if it collides with a core block id). */
  registerBlock<TAttrs>(manifest: BlockManifest<TAttrs>): void;
  registerDashboardCard(manifest: DashboardCardManifest): void;
  /** Add a "Force regenerate" entry to the Themes page menu. */
  registerRegenerationTarget(target: RegenerationTarget): void;
  /** Add an Inspector tab to the post/page editor (API ≥ 1.2). */
  registerInspectorTab(manifest: InspectorTabManifest): void;
  /** Add a section to the Categories/Tags editor (API ≥ 1.2). */
  registerTermEditorSection(manifest: TermEditorSectionManifest): void;
  /** Add an editor variant provider (API ≥ 1.3). */
  registerEditorVariantProvider(manifest: EditorVariantProvider): void;
}

