// ═══════════════════════════════════════════════════════════════════════════
// Publish target files (services/siteFiles.ts, services/storage/*)
// ═══════════════════════════════════════════════════════════════════════════

/** Input of `uploadFile`. */
export interface UploadFileOptions {
  /** Site path, no leading slash ("data/index.json"). */
  path: string;
  /** UTF-8 text, or base64 (without `data:` prefix) when `encoding === "base64"`. */
  content: string;
  encoding?: "utf-8" | "base64";
  signal?: AbortSignal;
}

export interface ListItem {
  path: string;
  type: "file" | "folder";
  size?: number;
  url?: string;
  depth?: number;
}

export interface ListResponse {
  items: ListItem[];
  page: number;
  per_page: number;
  total?: number;
}

/**
 * How a connector applies writes: "files" (immediately), "commit" (one git
 * commit per batch), "deployment" (whole-site snapshot).
 */
export type PublishModel = "files" | "commit" | "deployment";

/** Optional operations a connector supports natively. */
export interface StorageCapabilities {
  list: boolean;
  rename: boolean;
  renameFolder: boolean;
  folders: boolean;
  deletePrefix: boolean;
}

export interface PutInput {
  path: string;
  content: string;
  encoding?: "utf-8" | "base64";
}

/** One staged operation handed to `commitBatch`. */
export type BatchOp =
  | ({ type: "put" } & PutInput)
  | { type: "delete"; path: string }
  | { type: "deletePrefix"; path: string };

/** Contract of a publish connector (API ≥ 1.4). */
export interface StorageConnector {
  id: string;
  model: PublishModel;
  capabilities: StorageCapabilities;
  put(input: PutInput, signal?: AbortSignal): Promise<void>;
  /** UTF-8 text content; throw a 404 `StorageError` when missing. */
  get(path: string): Promise<string>;
  /** Raw bytes; null when missing (no toast). */
  getBytes?(path: string): Promise<Uint8Array | null>;
  /** MUST resolve when the file is already gone. */
  delete(path: string, signal?: AbortSignal): Promise<void>;
  publicUrl(path: string): Promise<string>;
  deletePrefix?(path: string): Promise<void>;
  rename?(oldPath: string, newPath: string): Promise<void>;
  renameFolder?(oldPath: string, newPath: string): Promise<void>;
  createFolder?(path: string): Promise<void>;
  list?(page: number, perPage: number): Promise<ListResponse>;
  /** Required for "commit" / "deployment" models. */
  commitBatch?(ops: BatchOp[]): Promise<void>;
}

/** Builds a connector from the settings stored in `config/storage`. */
export interface StorageConnectorFactory<S = Record<string, unknown>> {
  id: string;
  create(settings: S): StorageConnector;
}

/**
 * Error thrown by every publish-target failure. `status` is the HTTP status
 * (501 = "not supported by this target"). A translated toast has usually
 * already been shown when you catch it.
 */
export declare class StorageError extends Error {
  readonly status: number;
  readonly body?: string | undefined;
  constructor(message: string, status: number, body?: string);
}

