// ═══════════════════════════════════════════════════════════════════════════
// VALUES — exactly what <admin>/runtime/cms-runtime.js exports
// ═══════════════════════════════════════════════════════════════════════════

// ── API versioning ─────────────────────────────────────────────────────────

/** Runtime API version of the running admin, e.g. "1.4.0". */
export declare const CMS_API_VERSION: string;
/** Oldest `apiVersion` the running admin still loads. */
export declare const CMS_API_MIN_VERSION: string;

// ── Plugin API + registries ────────────────────────────────────────────────

/** The same object handed to `register(api)`. Prefer the `api` argument inside `register`. */
export declare const pluginApi: PluginApi;

/**
 * Runs every filter of `hook` in priority order, threading the value
 * (awaits async handlers). Use it to expose your own extension points.
 */
export declare function applyFilters<T>(hook: string, value: T, ...args: unknown[]): Promise<T>;

/** Synchronous `applyFilters`; throws if a handler returns a Promise. */
export declare function applyFiltersSync<T>(hook: string, value: T, ...args: unknown[]): T;

/** Runs every action of `hook` sequentially in priority order. */
export declare function doAction(hook: string, ...args: unknown[]): Promise<void>;

/** Same as `api.registerBlock`. Prefer the `api` argument inside `register()`. */
export declare function registerBlock<TAttrs>(manifest: BlockManifest<TAttrs>): void;
/** Same as `api.registerDashboardCard`. */
export declare function registerDashboardCard(manifest: DashboardCardManifest): void;
/** Same as `api.registerInspectorTab` (API ≥ 1.2). */
export declare function registerInspectorTab(manifest: InspectorTabManifest): void;
/** Same as `api.registerTermEditorSection` (API ≥ 1.2). */
export declare function registerTermEditorSection(manifest: TermEditorSectionManifest): void;
/** Same as `api.registerEditorVariantProvider` (API ≥ 1.3). */
export declare function registerEditorVariantProvider(manifest: EditorVariantProvider): void;

/**
 * Registers a plugin manifest in the admin's external registry. The external
 * loader does this for you with your bundle's default export — you normally
 * just `export default manifest`.
 */
export declare function registerExternalPlugin(manifest: PluginManifest): void;
/** Theme counterpart of `registerExternalPlugin` (normally done by the loader). */
export declare function registerExternalTheme(manifest: ThemeManifest): void;

/**
 * Adds a publish connector (API ≥ 1.4): a ready instance or a factory built
 * from the `settings` stored in `config/storage`. Re-registering an id replaces it.
 */
export declare function registerStorageConnector(
  entry: StorageConnector | StorageConnectorFactory,
): void;

// ── core/slug — URLs + slugs ───────────────────────────────────────────────

/** Lower-case ASCII, dash-separated slug (diacritics stripped, max 96 chars). "" for empty input. */
export declare function slugify(input: string): string;
/** True when `slug` is non-empty lower-case `a-z0-9` words joined by single dashes. */
export declare function isValidSlug(slug: string): boolean;
/** `base`, else `base-2`, `base-3`… — the first value for which `isUsed` returns false. */
export declare function findAvailableSlug(base: string, isUsed: (slug: string) => boolean): string;

export interface BuildPostUrlInput {
  post: Pick<Post, "type" | "slug">;
  primaryTerm?: Pick<Term, "type" | "slug"> | null;
}
/**
 * Site path of a post/page (no leading slash): page → "<slug>.html",
 * post with category → "<category>/<slug>.html", else "<slug>.html".
 * Throws on empty slugs.
 */
export declare function buildPostUrl(input: BuildPostUrlInput): string;
/** Archive path of a CATEGORY: "<slug>/index.html". Throws for tags and empty slugs. */
export declare function buildTermUrl(term: Pick<Term, "type" | "slug">): string;
/** Joins a base URL and a site path: ("https://x.com/", "/a.html") → "https://x.com/a.html". */
export declare function pathToPublicUrl(baseUrl: string, path: string): string;
/** Strips a trailing "index.html" ("fr/index.html" → "fr/"). */
export declare function canonicalPath(path: string): string;
/** Canonical absolute URL (`index.html` stripped). "" when `baseUrl` is empty. Use for canonical / og:url / hreflang. */
export declare function canonicalUrl(baseUrl: string, path: string): string;

/** Entity owning a public path (collision reports). */
export interface PathOwner {
  kind: "post" | "page" | "category";
  id: string;
  label: string;
  path: string;
}
/**
 * Returns who already owns `candidatePath` among posts/pages/categories, or
 * null. Pass the edited entity's id as `ignoreId` so it doesn't collide with itself.
 */
export declare function detectPathCollision(
  candidatePath: string,
  posts: Array<Pick<Post, "id" | "type" | "title" | "slug" | "primaryTermId">>,
  pages: Array<Pick<Post, "id" | "type" | "title" | "slug">>,
  terms: Array<Pick<Term, "id" | "type" | "name" | "slug">>,
  ignoreId?: string,
): PathOwner | null;
/** Same-type term slug collision check (a tag and a category may share a slug). */
